B.bip={Steinpilz:0,Sommersteinpilz:1,Kiefernsteinpilz:2,"Bronzer\xf6hrling":3,"Maronenr\xf6hrling":4,Birkenpilz:5,Butterpilz:6,"K\xf6rnchenr\xf6hrling":7,Ziegenlippe:8,"Rotfu\xdfr\xf6hrling":9,"Flockenstieliger Hexenr\xf6hrling":10,"Netzstieliger Hexenr\xf6hrling":11,"Gallenr\xf6hrling":12,"Satansr\xf6hrling":13,"Sch\xf6nfu\xdfr\xf6hrling":14,Rotkappe:15,Espenrotkappe:16,Birkenrotkappe:17,"Goldr\xf6hrling":18,"Sandr\xf6hrling":19,Pfifferling:20,"Falscher Pfifferling":21,Trompetenpfifferling:22,Herbsttrompete:23,Semmelstoppelpilz:24,"Krause Glucke":25,Habichtspilz:26,Ziegenbart:27,Igelstachelbart:28,Wiesenchampignon:29,Anischampignon:30,Waldchampignon:31,Karbolchampignon:32,Stadtchampignon:33,Parasol:34,Safranschirmling:35,Schopftintling:36,Fliegenpilz:37,Perlpilz:38,Pantherpilz:39,"Gr\xfcner Knollenbl\xe4tterpilz":40,"Kegelh\xfctiger Knollenbl\xe4tterpilz":41,"Fr\xfchjahrsknollenbl\xe4tterpilz":42,Scheidenstreifling:43,"Frauent\xe4ubling":44,"Gr\xfcngefelderter T\xe4ubling":45,"Speiset\xe4ubling":46,"Speit\xe4ubling":47,"Ledert\xe4ubling":48,Fichtenreizker:49,"Grubiger Milchling":50,Edelreizker:51,Lachsreizker:52,Kiefernreizker:53,Mohrenkopfmilchling:54,"Br\xe4tling":55,Speisemorchel:56,Spitzmorchel:57,"K\xe4ppchenmorchel":58,"B\xf6hmische Verpel":59,"Fr\xfchjahrslorchel":60,Morchelbecherling:61,"Flaschenst\xe4ubling":62,Riesenbovist:63,"Birnenst\xe4ubling":64,Austernseitling:65,Lungenseitling:66,Schwefelporling:67,Leberpilz:68,Judasohr:69,"Stockschw\xe4mmchen":70,"Gifth\xe4ubling":71,"Samtfu\xdfr\xfcbling":72,"Gr\xfcnbl\xe4ttriger Schwefelkopf":73,Hallimasch:74,"Dunkler Hallimasch":75,Maipilz:76,"Ziegelroter Risspilz":77,"Riesenr\xf6tling":78,"M\xf6nchskopf":79,Nebelkappe:80,"Violetter R\xf6telritterling":81,"Violetter Lacktrichterling":82,"Kahler Krempling":83,"Spitzgebuckelter Raukopf":84,"Orangefuchsiger Raukopf":85,Tigerritterling:86,"Gr\xfcnling":87,Nelkenschwindling:88,"Rehbrauner Dachpilz":89,"Riesentr\xe4uschling":90,"Fuchsiger R\xf6telritterling":91,Reifpilz:92}
B.bvx=new A.bL(["Wei\xdf und fest, verf\xe4rbt sich im Schnitt NICHT; unter der Huthaut bleibt es wei\xdf.","Angenehm nussig, mild im Geschmack.","F\xfcnf bis 25 cm, halbkugelig bis polsterf\xf6rmig, hell- bis dunkelbraun, matt, bei Feuchtigkeit leicht klebrig; der Rand bleibt oft heller.","Bauchig bis keulig, wei\xdflich bis hellbraun, mit feinem WEISSEM Netz auf hellem Grund, meist nur im oberen Teil.","R\xf6hren, jung wei\xdf, sp\xe4ter gelb bis olivgr\xfcn; am Stiel ausgebuchtet angewachsen und leicht vom Hut zu l\xf6sen.","Mykorrhiza bei Fichte, Kiefer, Buche und Eiche; Juni bis November, Hauptzeit August und September."])
B.buy=new A.bL(["Wei\xdf und fest, unver\xe4ndert im Schnitt; im Alter schnell weich.","Nussig, mild \u2014 wie der Steinpilz.","Sechs bis 20 cm, hell- bis ockerbraun, matt und feinsamtig; die Huthaut rei\xdft bei Trockenheit FEINRISSIG auf.","Bauchig, hellbraun, mit wei\xdfem Netz \xfcber den GANZEN Stiel bis zur Basis \u2014 beim Steinpilz nur oben.","R\xf6hren jung wei\xdf, sp\xe4ter gelb bis olivgr\xfcn, ausgebuchtet angewachsen.","W\xe4rmeliebend bei Eiche und Buche; schon ab Mai bis Oktober, der fr\xfcheste der Steinpilze."])
B.bvF=new A.bL(["Wei\xdf, unter der Huthaut r\xf6tlich, unver\xe4ndert im Schnitt.","Nussig und mild, wie beim Steinpilz.","Sechs bis 25 cm, rotbraun bis weinbraun, jung fast kugelig, matt, oft mit runzeliger Oberfl\xe4che.","Kr\xe4ftig bauchig, r\xf6tlichbraun get\xf6nt, mit wei\xdfem bis r\xf6tlichem Netz im oberen Teil.","R\xf6hren jung wei\xdf, sp\xe4ter gelblich bis olivgr\xfcn.","Bei Kiefer und Fichte auf sauren, sandigen B\xf6den, oft im Gebirge; Juni bis Oktober."])
B.buG=new A.bL(["Wei\xdf, fest, unver\xe4ndert im Schnitt.","Angenehm nussig, mild.","Sechs bis 20 cm, sehr dunkel bronze- bis schwarzbraun, jung samtig, wirkt fast ru\xdfig.","Bauchig, braun mit feinem wei\xdflichem bis br\xe4unlichem Netz.","R\xf6hren jung wei\xdf, sp\xe4ter gelb bis olivgr\xfcn.","W\xe4rmeliebend bei Eiche und Edelkastanie, in Deutschland selten und im S\xfcden; Juli bis September."])
B.bvE=new A.bL(["Wei\xdflich bis blassgelb, im Schnitt schwach blauend.","Mild, unauff\xe4llig pilzig.","F\xfcnf bis 15 cm, kastanien- bis dunkelbraun, jung samtig matt, bei N\xe4sse schmierig gl\xe4nzend.","Schlank, hellbraun l\xe4ngsfaserig, OHNE Netz.","R\xf6hren jung blassgelb, sp\xe4ter gr\xfcnlichgelb; auf Druck deutlich BLAUEND.","Mykorrhiza vor allem bei Fichte und Kiefer, auf sauren B\xf6den; Juli bis November."])
B.bvn=new A.bL(["Wei\xdf, weich, im Alter schwammig; im Schnitt kaum verf\xe4rbend.","Mild und unauff\xe4llig.","F\xfcnf bis 15 cm, graubraun bis hellbraun, halbkugelig, sp\xe4ter polsterf\xf6rmig, trocken bis leicht schmierig.","Lang und schlank, wei\xdflich mit dunklen SCH\xdcPPCHEN in L\xe4ngsreihen \u2014 kein Netz.","R\xf6hren wei\xdflich bis graubraun, auf Druck kaum verf\xe4rbend.","Ausschlie\xdflich bei Birken; Juni bis Oktober."])
B.bux=new A.bL(["Wei\xdflich bis gelb, weich, ohne Verf\xe4rbung.","Mild, schwach obstig.","F\xfcnf bis zw\xf6lf cm, kastanienbraun, bei Feuchtigkeit stark SCHLEIMIG gl\xe4nzend; die Huthaut l\xe4sst sich abziehen.","Gelblich, mit deutlichem h\xe4utigem RING; oberhalb davon fein gek\xf6rnelt.","R\xf6hren blassgelb, fein, jung von einem wei\xdfen Velum bedeckt.","Nur bei Kiefern, gern an Wegr\xe4ndern und auf jungen Aufforstungen; Juni bis November."])
B.bvB=new A.bL(["Blassgelb, weich, ohne Verf\xe4rbung.","Mild, unauff\xe4llig.","Vier bis zehn cm, ocker- bis rotbraun, schmierig gl\xe4nzend.","Blassgelb, im oberen Teil fein gek\xf6rnelt \u2014 OHNE Ring.","R\xf6hren blassgelb; bei jungen Pilzen treten milchige TR\xd6PFCHEN aus den Poren.","Bei Kiefern, oft auf kalkhaltigem Boden; Juni bis Oktober."])
B.bv_=new A.bL(["Wei\xdflich bis blassgelb, unter der Huthaut NICHT rot.","Mild, schwach obstig.","Vier bis zehn cm, ocker- bis olivbraun, samtig matt, im Alter oft feinrissig.","Blassgelb bis br\xe4unlich, l\xe4ngsfaserig, ohne Rot.","R\xf6hren leuchtend gelb, weit und eckig, auf Druck schwach blauend.","Bei Laub- und Nadelb\xe4umen, gern an moosigen Stellen; Juni bis Oktober."])
B.bv2=new A.bL(["Gelblich, unter der Huthaut r\xf6tlich, im Schnitt schwach blauend.","Mild und unauff\xe4llig.","Drei bis acht cm, olivbraun, samtig, im Alter felderig aufrei\xdfend \u2014 in den Rissen zeigt sich ROTES Fleisch.","Schlank, gelblich mit deutlich ROTER \xdcberfaserung.","R\xf6hren gelb, weit, auf Druck blauend.","Bei Laub- und Nadelb\xe4umen, h\xe4ufig; Juni bis Oktober."])
B.buI=new A.bL(["Gelb, im Schnitt augenblicklich tiefblau.","Mild, angenehm pilzig.","Sechs bis 20 cm, dunkel olivbraun bis schwarzbraun, samtig matt.","Kr\xe4ftig, gelb mit roten FLOCKEN \u2014 ausdr\xfccklich ohne Netz.","R\xf6hren ROT bis orangerot, auf Druck sofort schwarzblau.","Bei Fichte, Buche und Eiche, auf sauren B\xf6den; Mai bis Oktober."])
B.bvs=new A.bL(["Gelb, im Schnitt sofort dunkelblau.","Mild bis schwach s\xe4uerlich.","Acht bis 20 cm, olivbraun bis graubraun, samtig, bei Druck blauend.","Gelb bis orange mit feinem ROTEM NETZ.","R\xf6hren rot bis orangerot, sofort blauend; \xfcber den R\xf6hren liegt eine rote Linie am Hutfleisch.","Bei Buche und Eiche auf kalkhaltigem Boden; Juni bis Oktober."])
B.buU=new A.bL(["Wei\xdf, im Schnitt manchmal schwach rosa anlaufend.","Geruch unauff\xe4llig, Geschmack GALLENBITTER \u2014 ein winziges St\xfcck auf der Zungenspitze gen\xfcgt; ausspucken.","F\xfcnf bis 15 cm, hell lederbraun, matt und trocken \u2014 dem Steinpilz t\xe4uschend \xe4hnlich.","Hellbraun mit grobem, DUNKLEM Netz auf hellem Grund.","R\xf6hren jung wei\xdf, sp\xe4ter deutlich ROSA bis fleischrosa.","Bei Fichte und Buche auf sauren B\xf6den, oft an Baumst\xfcmpfen; Juni bis Oktober."])
B.bv4=new A.bL(["Wei\xdflich bis gelblich, im Schnitt nur schwach blauend.","Alt unangenehm, aasartig s\xfc\xdflich.","Zehn bis 30 cm, wei\xdflich bis hellgrau, oft wie schmutzig wirkend, polsterf\xf6rmig.","Dick und bauchig, gelb bis rot, mit feinem rotem NETZ.","R\xf6hren jung gelb, bald ROT bis orangerot; auf Druck schwach blauend.","W\xe4rmeliebend bei Eiche, Buche und Linde auf Kalk; Juni bis September, im Norden selten."])
B.bvM=new A.bL(["Blassgelb, im Schnitt blauend.","Unauff\xe4llig, Geschmack deutlich BITTER \u2014 ein St\xfcckchen auf der Zunge gen\xfcgt; ausspucken.","F\xfcnf bis 15 cm, hell graubraun bis olivgrau, matt und feinfilzig \u2014 dem Steinpilz \xe4hnlich.",'Kr\xe4ftig, oben gelb, nach unten leuchtend ROT, mit feinem ROTEM NETZ; der \u201esch\xf6ne Fu\xdf", der ihm den Namen gibt.',"R\xf6hren GELB, auch im Alter, auf Druck blauend \u2014 nie rot.","In Nadel- und Laubw\xe4ldern auf sauren B\xf6den, h\xe4ufig im Gebirge; Juli bis Oktober."])
B.buB=new A.bL(["Wei\xdf, im Schnitt erst weinrot bis grau, dann schwarz anlaufend; jung fest, alt schwammig.","Angenehm pilzig, Geschmack mild.","F\xfcnf bis 20 cm, halbkugelig und lange geschlossen, orange bis ziegelrot; die Huthaut steht am Rand etwas \xfcber den R\xf6hren vor.","Lang und schlank, wei\xdflich, dicht mit SCHUPPEN besetzt, die je nach Art wei\xdf, rotbraun oder schwarz sind.","R\xf6hren jung wei\xdflich bis grau, auf Druck graubraun anlaufend, am Stiel frei bleibend und fein.","Mykorrhiza bei Birke, Espe, Eiche und Nadelb\xe4umen; der deutsche Name meint MEHRERE Arten. Juni bis Oktober."])
B.bvu=new A.bL(["Wei\xdf, im Anschnitt rasch violettgrau und dann schwarz; fest und dickfleischig.","Angenehm pilzig, Geschmack mild \u2014 roh jedoch unvertr\xe4glich.","Sechs bis 20 cm, leuchtend orangerot bis ziegelrot, trocken und feinfilzig, alt etwas runzelig.","Kr\xe4ftig und keulig, wei\xdf, mit anfangs WEISSLICHEN, sp\xe4ter rotbraunen Schuppen.","R\xf6hren wei\xdflich bis cremegrau, auf Druck br\xe4unend, am Stiel ausgebuchtet angewachsen.","Mykorrhiza bei Espe und Pappel, seltener bei Eiche; Juni bis Oktober."])
B.bvm=new A.bL(["Wei\xdf, im Schnitt rosa bis graurot, dann schwarzgrau; im Stielgrund blaugr\xfcn.","Mild und unauff\xe4llig; roh unvertr\xe4glich.","F\xfcnf bis 20 cm, orange bis gelbbraun, matt und feinfilzig, mit deutlich \xfcberstehender Huthaut am Rand.","Hoch und schlank, wei\xdf mit SCHWARZEN Schuppen, zur Basis hin oft blaugr\xfcn fleckend.","R\xf6hren grauwei\xdf, auf Druck schmutzig grau; die Poren sind sehr fein und rund.","Mykorrhiza ausschlie\xdflich bei Birke, gern in feuchten Mooren und Heiden; Juni bis Oktober."])
B.bvK=new A.bL(["Hellgelb, weich, im Schnitt kaum verf\xe4rbend.","Schwach s\xe4uerlich, Geschmack mild.","Vier bis zw\xf6lf cm, goldgelb bis rotbraun, bei Feuchtigkeit stark SCHLEIMIG und gl\xe4nzend, trocken lackartig.","Gelb, oberhalb des h\xe4utigen RINGES genetzt, unterhalb rotbraun gefleckt.","R\xf6hren jung zitronengelb, sp\xe4ter ockergelb, am Stiel kurz herablaufend; jung von einem Velum verdeckt.","Mykorrhiza AUSSCHLIESSLICH bei L\xe4rche; Juli bis Oktober."])
B.bv3=new A.bL(["Blassgelb, weich, im Schnitt schwach blauend.","Streng s\xe4uerlich, fast nach Chlor; Geschmack mild.","F\xfcnf bis 14 cm, ockergelb bis semmelbraun, feinschuppig-k\xf6rnig und nur bei N\xe4sse leicht klebrig.","Kr\xe4ftig und walzig, gelblich bis ockerbraun, ohne Ring und ohne Netz.","R\xf6hren jung olivgrau, sp\xe4ter zimtbraun, sehr feinporig, auf Druck schwach blauend.","Mykorrhiza bei Kiefer auf Sandb\xf6den und in Heiden; Juli bis November."])
B.bvL=new A.bL(["Wei\xdflich bis blassgelb, faserig, nicht brechend.","Deutlich nach Aprikose, Geschmack mild bis leicht pfeffrig.","Drei bis zehn cm, dottergelb, jung gew\xf6lbt, sp\xe4ter trichterig mit welligem, eingerolltem Rand.","Voll und fest, dottergelb, nach unten verj\xfcngt, ohne scharfen \xdcbergang zum Hut.","Stumpfe, dicke LEISTEN \u2014 keine echten Lamellen \u2014, gegabelt und weit am Stiel herablaufend, in derselben Farbe wie der Hut.","Mykorrhiza bei Fichte, Buche und Eiche, gern in Moos; Juni bis Oktober."])
B.buz=new A.bL(["Weich, gelblich, d\xfcnn.","Unauff\xe4llig, kein Aprikosenduft.","Zwei bis sechs cm, orangegelb bis orangerot, samtig, mit lange eingerolltem Rand.","Schlank, oft verbogen, orange, vom Hut deutlich abgesetzt.","Echte LAMELLEN, fein, dicht stehend, wiederholt gegabelt, kr\xe4ftiger orange als der Hut.","Auf Nadelstreu, morschem Holz und in Heidegebieten; August bis November."])
B.bvy=new A.bL(["D\xfcnn, z\xe4h-elastisch, blassgelb.","Schwach obstig, mild.","Zwei bis sechs cm, graubraun, trichterig mit welligem Rand, in der Mitte meist durchbohrt.","Deutlich GELB, hohl, l\xe4ngsrillig.","Graue bis gelbliche LEISTEN, weit herablaufend, dick und gegabelt.","In Nadel- und Mischw\xe4ldern, in Moos und auf saurem Boden, oft in gro\xdfen Trupps; August bis Dezember."])
B.bvb=new A.bL(["D\xfcnn, z\xe4h-elastisch, grau.","Angenehm w\xfcrzig, getrocknet intensiv.","F\xfcnf bis zw\xf6lf cm, trichter- bis trompetenf\xf6rmig, bis zum Stiel durchgehend hohl, grauschwarz, au\xdfen faserschuppig.","Nicht abgesetzt: Die ganze Trompete ist Hut und Stiel in einem, durchgehend grauschwarz.","Nahezu glatt, h\xf6chstens schwach aderig, aschgrau bereift \u2014 keine Leisten und keine Lamellen.","Bei Buche und Eiche auf kalkhaltigem Boden, im Laub leicht zu \xfcbersehen; August bis November."])
B.buO=new A.bL(["Wei\xdf, br\xfcchig, im Alter etwas bitter.","Mild bis leicht scharf, angenehm.","Drei bis zehn cm, cremefarben bis semmelgelb, unregelm\xe4\xdfig gebuckelt, matt und trocken.","Kurz und dick, wei\xdflich, oft exzentrisch angesetzt.","Weiche, wei\xdfliche STACHELN, die sich leicht abstreifen lassen und am Stiel herablaufen.","In Laub- und Nadelw\xe4ldern, oft in Reihen oder Hexenringen; August bis November."])
B.buQ=new A.bL(["Z\xe4h-elastisch, bei jungen St\xfccken zart, im Alter ledrig und br\xfcchig.","W\xfcrzig, fast nach Anis oder Marzipan; Geschmack mild und nussig.","Kein Hut: ein 10 bis 40 cm gro\xdfer, blumenkohlartiger Ballen aus krausen, BANDF\xd6RMIGEN Lappen, cremewei\xdf bis ockergelb.","Ein kurzer, wurzelnder Strunk, der in die Baumwurzel \xfcbergeht.","Weder Lamellen noch Poren; die Sporen sitzen glatt auf der Unterseite der Lappen.","Am Stammfu\xdf von KIEFERN, seltener anderer Nadelb\xe4ume, oft jahrelang an derselben Stelle; August bis November."])
B.buY=new A.bL(["Wei\xdflich bis graubraun, jung fest, im Alter z\xe4h.","W\xfcrzig; jung mild, mit dem Alter zunehmend BITTER.","Acht bis 25 cm, graubraun, trichterig vertieft und mit groben, aufgerichteten SCHUPPEN wie ein Vogelgefieder besetzt.","Kurz und dick, graubraun, oft seitlich am Hut angesetzt.","STACHELN statt Lamellen, grau bis braun, am Stiel deutlich herablaufend.","Mykorrhiza bei Fichte auf saurem Boden im Bergwald; August bis Oktober."])
B.bv7=new A.bL(["Wei\xdf bis blass, br\xfcchig; bei manchen Arten auf Druck weinrot fleckend.","Unauff\xe4llig bis leicht erdig; bitterer Geschmack spricht gegen einen Speisepilz.","Kein Hut: ein f\xfcnf bis 20 cm hoher, korallenartig verzweigter Busch, je nach Art ocker, gelb, rosa oder violett gespitzt.","Ein dicker, wei\xdflicher Strunk, aus dem sich die \xc4ste wiederholt gabeln.","Weder Lamellen noch Poren; die Sporen sitzen au\xdfen an den \xc4sten.","Auf Waldboden bei Laub- und Nadelb\xe4umen; der deutsche Name meint die ganze Gattung. Juli bis Oktober."])
B.bvN=new A.bL(["Wei\xdf, weich und faserig, im Alter gilbend und z\xe4h.","Angenehm pilzig, Geschmack mild.","Kein Hut: ein f\xfcnf bis 25 cm gro\xdfer, rein wei\xdfer Klumpen, von dem lange, herabh\xe4ngende STACHELN wie ein Bart ausgehen.","Kein Stiel; der Fruchtk\xf6rper sitzt mit schmaler Basis direkt am Stamm.","Weder Lamellen noch Poren; die Stacheln selbst tragen die Sporen.","An Wunden lebender Laubb\xe4ume, vor allem Buche und Eiche; in Deutschland besonders gesch\xfctzt. September bis November."])
B.bvX=new A.bL(["Wei\xdf, im Schnitt allenfalls schwach r\xf6tend, nie chromgelb.","Angenehm nach Champignon, mild.","Vier bis zehn cm, wei\xdf bis cremefarben, seidig, jung halbkugelig.","Wei\xdf, mit einfachem, verg\xe4nglichem RING \u2014 ohne Scheide und ohne Knolle.","Lamellen jung ROSA, dann rotbraun, zuletzt schokoladenbraun; frei, den Stiel nicht ber\xfchrend.","Auf Weiden, Wiesen und in Parks, nie im Wald an Holz; Mai bis Oktober."])
B.bv0=new A.bL(["Wei\xdf, langsam gilbend, besonders an der Stielbasis.","Deutlich nach ANIS oder Marzipan \u2014 das entscheidende Merkmal.","Acht bis 20 cm, wei\xdf, seidig gl\xe4nzend, auf Druck gilbend.","Wei\xdf, mit breitem, zweilagigem Ring; Basis knollig verdickt.","Lamellen jung blassgrau bis rosa, sp\xe4ter schokoladenbraun, frei.","Auf Wiesen, Weiden und an Waldr\xe4ndern; Juni bis Oktober."])
B.bvq=new A.bL(["Wei\xdf, im Schnitt deutlich R\xd6TEND, nie gelb.","Angenehm pilzig, mild.","F\xfcnf bis zehn cm, blassbraun mit r\xf6tlichbraunen Sch\xfcppchen.","Wei\xdflich, mit h\xe4ngendem Ring, Basis wenig verdickt.","Lamellen jung blassrosa, sp\xe4ter dunkelbraun, frei.","In Nadelw\xe4ldern, gern bei Fichte; Juli bis Oktober."])
B.bvp=new A.bL(["Wei\xdf, in der Stielbasis leuchtend chromgelb verf\xe4rbend.","Nach KARBOL, Tinte oder Krankenhaus \u2014 beim Erhitzen un\xfcberriechbar.","F\xfcnf bis 15 cm, wei\xdf, oben oft flach abgeflacht wie abgeschnitten, grau \xfcberhaucht.","Wei\xdf mit breitem Ring; die Basis l\xe4uft angeritzt sofort CHROMGELB an.","Lamellen jung wei\xdflich bis blassgrau, sp\xe4ter schokoladenbraun, frei.","In Parks, G\xe4rten und an Waldr\xe4ndern, gern unter Hecken; Juli bis Oktober."])
B.bvY=new A.bL(["Wei\xdf, sehr fest, im Schnitt kaum verf\xe4rbend.","Angenehm nach Champignon, Geschmack mild; kein Anis und keine Tinte.","F\xfcnf bis 15 cm, wei\xdf bis cremefarben, dickfleischig, lange flach gew\xf6lbt und oft vom Aufstemmen der Erde rissig.","Kurz und dick, wei\xdf, mit DOPPELTEM Ring \u2014 einem oberen h\xe4utigen und einem unteren, wulstigen.","Lamellen jung blassrosa, dann schokoladenbraun, frei stehend und sehr dicht.","An Wegr\xe4ndern, auf Parkrasen und in Pflasterritzen, oft mitten in St\xe4dten; Mai bis Oktober."])
B.buR=new A.bL(["Wei\xdf, im Schnitt unver\xe4ndert oder allenfalls schwach br\xe4unend.","Angenehm nussig, mild.","Zehn bis 30 cm, jung paukenschl\xe4gelf\xf6rmig geschlossen, sp\xe4ter flach ausgebreitet mit dunklem Buckel und groben braunen Schuppen auf hellem Grund.","Sehr lang, hohl, mit deutlicher SCHLANGENHAUT-Natterung, knolliger Basis und einem VERSCHIEBBAREN Ring.","Lamellen wei\xdf, weich, frei, durch ein Collar vom Stiel getrennt.","Auf Wiesen, Waldwegen und Lichtungen; Juli bis Oktober."])
B.buM=new A.bL(["Wei\xdf, im Schnitt deutlich SAFRAN- bis orangerot anlaufend.","Angenehm pilzig, mild.","Acht bis 20 cm, hell mit groben, wolligen Schuppen, ohne ausgepr\xe4gte Natterung am Stiel.","Glatt bis schwach faserig, NICHT genattert, mit verschiebbarem Ring und dicker Knolle.","Lamellen wei\xdf, auf Druck r\xf6tend, frei.","In G\xe4rten, an Komposthaufen und in Nadelw\xe4ldern; Juli bis Oktober."])
B.bvI=new A.bL(["Jung wei\xdf und zart, altert von unten her schwarz und fl\xfcssig.","Mild und angenehm; brauchbar NUR jung mit rein wei\xdfen Lamellen.","Vier bis 15 cm hoch, walzlich-eif\xf6rmig wie eine Per\xfccke, wei\xdf mit abstehenden br\xe4unlichen SCHUPPEN; \xf6ffnet sich nie ganz.","Lang, schlank und hohl, wei\xdf, mit einem beweglichen schmalen Ring.","Lamellen jung wei\xdf, dann von unten her rosa, schlie\xdflich schwarz und zu Tinte zerflie\xdfend.","Auf ged\xfcngten Wiesen, an Wegr\xe4ndern und in G\xe4rten, oft in Reihen; Mai bis November."])
B.bvf=new A.bL(["Wei\xdf, unter der Huthaut gelblich, ohne Verf\xe4rbung.","Unauff\xe4llig und mild \u2014 der Geruch warnt hier nicht.","Acht bis 20 cm, leuchtend scharlachrot mit wei\xdfen Velumflocken, die der Regen abwaschen kann.","Wei\xdf, mit h\xe4ngendem Ring und einer Knolle, die von g\xfcrtelartigen Velumresten umringt ist.","Lamellen rein wei\xdf und dicht gedr\xe4ngt, frei \u2014 sie ber\xfchren den Stiel nicht.","Bei Birke und Fichte auf sauren B\xf6den; Juli bis November."])
B.bv9=new A.bL(["Wei\xdf, an Fra\xdfstellen und im Schnitt deutlich WEINROT ANLAUFEND.","Mild, unauff\xe4llig.","F\xfcnf bis 15 cm, graurosa bis fleischbr\xe4unlich, mit schmutzigrosa Velumflocken.","Wei\xdflich bis rosa, mit deutlich GERIEFELTEM Ring, Basis r\xfcbenartig verdickt \u2014 ohne abgesetzte Knolle.","Lamellen wei\xdf, im Alter rosa gefleckt, frei.","Bei Fichte, Buche und Eiche; Juni bis Oktober."])
B.bvO=new A.bL(["Wei\xdf, im Schnitt UNVER\xc4NDERT \u2014 kein R\xf6ten.","Schwach rettichartig.","F\xfcnf bis zehn cm, graubraun bis olivbraun, mit rein WEISSEN, gleichm\xe4\xdfig verteilten Velumflocken; der Rand ist gerieft.","Wei\xdf, mit GLATTEM Ring und abgesetzter, gerandeter Knolle mit einem umlaufenden Wulst.","Lamellen rein wei\xdf, frei.","Bei Buche, Eiche und Fichte; Juni bis Oktober."])
B.buN=new A.bL(["Wei\xdf, ohne Verf\xe4rbung.","Jung unauff\xe4llig, alt s\xfc\xdflich-widerlich nach Honig.","F\xfcnf bis 15 cm, oliv- bis gelbgr\xfcn, radialfaserig, meist ohne Flocken; der Rand ist NICHT gerieft.","Wei\xdf bis gr\xfcnlich genattert, mit h\xe4ngendem Ring und einer h\xe4utigen, lappigen SCHEIDE am Stielgrund.","Lamellen rein wei\xdf und wei\xdf BLEIBEND, dicht, frei.","Bei Eiche und Buche, selten Fichte; Juli bis Oktober."])
B.bvU=new A.bL(["Wei\xdf, ohne Verf\xe4rbung.","Alt s\xfc\xdflich-unangenehm.","F\xfcnf bis zehn cm, rein wei\xdf, kegelig bis glockig, seidig gl\xe4nzend, oft schief.","Wei\xdf, flockig-faserig, mit fetzigem Ring und h\xe4utiger SCHEIDE.","Lamellen rein wei\xdf, gedr\xe4ngt, frei; sie bleiben auch im Alter wei\xdf.","In Nadel- und Bergw\xe4ldern auf saurem Boden; Juli bis Oktober."])
B.bvV=new A.bL(["Wei\xdf, ohne Verf\xe4rbung.","Unauff\xe4llig bis schwach s\xfc\xdflich.","F\xfcnf bis zehn cm, rein wei\xdf, glatt, jung glockig, sp\xe4ter ausgebreitet; der Rand ist nicht gerieft.","Wei\xdf, mit h\xe4ngendem Ring und h\xe4utiger SCHEIDE am Stielgrund.","Lamellen rein wei\xdf, gedr\xe4ngt und frei; keine Spur von Rosa, anders als bei jungen Champignons.","W\xe4rmeliebend bei Eiche und Buche auf Kalk; Mai bis Juli."])
B.buS=new A.bL(["Wei\xdf, d\xfcnn, zerbrechlich.","Unauff\xe4llig, ohne besonderen Geschmack.","F\xfcnf bis zehn cm, grau bis graubraun, glatt, der Rand auff\xe4llig stark GERIEFT.","Schlank, wei\xdflich, OHNE RING, aus einer weiten, h\xe4utigen Scheide kommend.","Lamellen wei\xdf, frei.","In Laub- und Nadelw\xe4ldern, gern an feuchten Stellen; Juni bis Oktober."])
B.bvv=new A.bL(["Wei\xdf, kr\xfcmelig brechend wie ein Apfel, ohne Milch.","Mild und nussig, ohne jede Sch\xe4rfe.","F\xfcnf bis 15 cm, violett-gr\xfcn-grau gemischt, oft mehrfarbig gescheckt; die Huthaut l\xe4sst sich zur H\xe4lfte abziehen.","Wei\xdf, fest, OHNE Ring und OHNE Scheide.","Lamellen wei\xdf, weich und biegsam \u2014 sie f\xfchlen sich speckig an und brechen nicht.","Bei Buche und Eiche; Juni bis Oktober."])
B.buD=new A.bL(["Wei\xdf, kr\xfcmelig, ohne Verf\xe4rbung.","Mild, angenehm nussig; kein scharfer Geschmack.","F\xfcnf bis zw\xf6lf cm, grasgr\xfcn bis graugr\xfcn, die Huthaut FELDERIG aufgerissen wie eine Krokodilhaut.","Wei\xdf, fest, ohne Ring und ohne Scheide.","Lamellen wei\xdf bis cremefarben, spr\xf6de.","Bei Buche und Eiche auf Kalk; Juni bis September."])
B.buv=new A.bL(["Wei\xdf, fest und kr\xfcmelig brechend, ohne Milch.","Mild, angenehm nussig \u2014 der Geschmack entscheidet.","F\xfcnf bis zehn cm, weinrot bis fleischrosa, oft ausblassend; die Huthaut endet kurz vor dem Rand, sodass die Lamellenenden hervorschauen.","Wei\xdf, fest, an der Basis oft rostfleckig.","Lamellen wei\xdf bis cremefarben, spr\xf6de brechend, am Stiel angewachsen.","Bei Buche und Eiche; Juni bis Oktober."])
B.buw=new A.bL(["Wei\xdf, unter der Huthaut r\xf6tlich.","Schwach obstig, Geschmack BRENNEND SCHARF \u2014 sofort ausspucken.","Vier bis zehn cm, leuchtend kirschrot, gl\xe4nzend; die Huthaut l\xe4sst sich fast vollst\xe4ndig abziehen.","Rein wei\xdf, zerbrechlich.","Lamellen rein wei\xdf, spr\xf6de.","In feuchten Nadelw\xe4ldern, gern in Sphagnum-Moos; Juli bis Oktober."])
B.buP=new A.bL(["Wei\xdf und fest, unter der Huthaut br\xe4unlich; OHNE Milch.","Schwach obstartig, Geschmack MILD \u2014 auch in den Lamellen.","F\xfcnf bis 13 cm, kastanien- bis purpurbraun, in der Mitte oft heller ocker, der Rand alt deutlich gerieft.","Wei\xdf und keulig, fest, ohne Ring; bricht wie Kreide, statt zu fasern.","Lamellen jung wei\xdf, reif kr\xe4ftig OCKERGELB durch das Sporenpulver, br\xfcchig.","Mykorrhiza bei Fichte und Tanne im Bergwald; Juli bis Oktober."])
B.bvA=new A.bL(["Blass orange und br\xfcchig; Milch KAROTTENROT, nach einer halben Stunde weinrot bis gr\xfcnlich.","Obstig, Geschmack mild bis leicht bitterlich.","F\xfcnf bis zw\xf6lf cm, orange mit undeutlichen Zonen, bald trichterig, auf Druck und im Alter rasch GR\xdcN fleckend.","Kurz und hohl, orange. Gr\xfcbchen K\xd6NNEN auftreten, meist flacher und blasser als beim Edelreizker \u2014 auf dieses Merkmal allein ist kein Verlass, der Baum entscheidet.","Lamellen orange, dicht, am Stiel herablaufend, mit der Zeit ebenfalls gr\xfcnfleckig.","Mykorrhiza AUSSCHLIESSLICH bei Fichte; Juli bis Oktober."])
B.bvW=new A.bL(["Wei\xdf und fest; Milch WEISS, an der Luft binnen Sekunden SCHWEFELGELB.","Unauff\xe4llig; die Milch schmeckt nach kurzer Zeit bitter und scharf.","Acht bis 20 cm, stroh- bis ockergelb, schwach gezont, trichterig vertieft; der Rand jung eingerollt und ZOTTIG-wollig.","Kurz, dick und hohl, blass mit auff\xe4lligen ockergelben GR\xdcBCHEN \u2014 wie beim Reizker; das Merkmal trennt die beiden nicht.","Lamellen cremewei\xdf, gedr\xe4ngt, kurz herablaufend, im Alter br\xe4unlich fleckig.","Mykorrhiza mit FICHTE, in Fichten- und Tannen-Buchenw\xe4ldern auf feuchtem, kalkhaltigem Boden im H\xfcgel- und Bergland; Juli bis November."])
B.bvR=new A.bL(["Wei\xdflich mit orangefarbenen Zonen; Milch karottenrot und \xfcber Stunden unver\xe4ndert.","Angenehm obstig, Geschmack mild und leicht harzig.","Vier bis 14 cm, orange mit deutlich konzentrischen ZONEN, trichterig vertieft, nur wenig und sp\xe4t gr\xfcnend.","Fest und hohl, orange, mit auff\xe4llig dunklen GR\xdcBCHEN gezeichnet; da auch der Fichtenreizker grubig sein kann, trennt das die beiden nicht f\xfcr sich allein.","Lamellen leuchtend orange, gedr\xe4ngt und weit am Stiel herablaufend.","Mykorrhiza bei Kiefer auf kalkhaltigem Boden; August bis Oktober."])
B.bve=new A.bL(["Cremefarben; Milch orangerot und an der Luft LANGSAM weinrot werdend.","Schwach obstartig, Geschmack mild bis leicht bitter.","Sechs bis 15 cm, lachs- bis aprikosenfarben, kaum gezont, der Rand lange eingerollt; gr\xfcnt nicht.","Kr\xe4ftig und lachsfarben, mit nur schwach angedeuteten Gr\xfcbchen.","Lamellen blass lachsfarben, sehr dicht stehend und am Stiel herablaufend.","Mykorrhiza AUSSCHLIESSLICH bei Wei\xdftanne; August bis Oktober."])
B.bvT=new A.bL(["Blass, im Schnitt weinrot; Milch von Anfang an DUNKEL WEINROT statt orange.","Mild und obstig, Geschmack mild.","F\xfcnf bis zw\xf6lf cm, ockerorange bis fleischrosa mit gr\xfcnlichen Flecken, nur schwach gezont.","Kurz und grubig, blass mit weinroten T\xf6nen.","Lamellen weinrot \xfcberhaucht und damit DUNKLER als bei den anderen Reizkern, dicht, herablaufend.","Mykorrhiza bei Kiefer auf Kalk, w\xe4rmeliebend; September bis November."])
B.bvk=new A.bL(["Wei\xdf, im Schnitt langsam rosa bis r\xf6tlich; Milch wei\xdf und r\xf6tend.","Unauff\xe4llig, Geschmack mild.","Drei bis acht cm, SAMTIG dunkelbraun bis fast schwarz, mit kleinem spitzem Buckel und gekerbtem Rand.","Lang und schlank, samtig dunkelbraun, oft l\xe4ngsrunzelig.","Lamellen auffallend WEISS bis cremefarben und weit stehend \u2014 der Kontrast zum Hut ist das Kennzeichen.","Mykorrhiza bei Fichte und Tanne im Bergwald, gern in Moos; Juli bis Oktober."])
B.bvl=new A.bL(["Wei\xdf und fest; Milch reichlich, WEISS wie Milch, klebrig und braun eintrocknend.","Deutlich nach HERINGSLAKE, Geschmack mild und nussig.","F\xfcnf bis 14 cm, orangebraun bis rostrot, matt und fein samtig, im Alter felderig rissig.","Fest und hart, in Hutfarbe, ohne Gr\xfcbchen und ohne Ring.","Lamellen cremewei\xdf und gedr\xe4ngt, auf Druck BRAUN fleckend, am Stiel kurz herablaufend.","Mykorrhiza bei Eiche, Buche und Hainbuche auf warmen B\xf6den; Juli bis September."])
B.buF=new A.bL(["D\xfcnn, wachsartig, komplett hohl. L\xe4ngs halbieren ist die Probe, die entscheidet.","Angenehm w\xfcrzig.","Vier bis zehn cm, eif\xf6rmig bis rundlich, ockerbraun, mit unregelm\xe4\xdfigen WABEN; mit dem Stiel vollst\xe4ndig verwachsen.","Wei\xdflich, kleiig, HOHL \u2014 und der Hohlraum geht ohne Unterbrechung in den Hut \xfcber.","Keine Lamellen und keine R\xf6hren \u2014 die Sporen sitzen in den Wabenkammern des Hutes.","In Auw\xe4ldern, G\xe4rten und auf Rindenmulch, gern bei Esche; April und Mai."])
B.bv5=new A.bL(["D\xfcnn, komplett hohl.","W\xfcrzig, angenehm.","Vier bis zw\xf6lf cm, kegelig-spitz, olivbraun bis schwarzbraun, mit L\xc4NGS verlaufenden Rippen und Querstegen.","Wei\xdflich, hohl, durchgehend mit dem Hut verbunden.","Keine Lamellen \u2014 Sporen in den Wabenkammern.","In Nadelw\xe4ldern, auf Brandstellen und Rindenmulch; April bis Juni."])
B.bva=new A.bL(["Sehr d\xfcnn, hohl, zerbrechlich.","Mild, unauff\xe4llig.","Zwei bis vier cm, kegelig, olivbraun, wabig \u2014 nur zur H\xc4LFTE mit dem Stiel verwachsen, der untere Rand steht frei ab.","Lang, wei\xdflich, kleiig, hohl.","Keine Lamellen; der freie Hutrand gibt den Blick auf den Stiel frei.","In Auw\xe4ldern und Geb\xfcschen, gern bei Esche und Pappel; April und Mai."])
B.bvj=new A.bL(["D\xfcnn, zerbrechlich.","Unauff\xe4llig, schwach pilzig.","Zwei bis f\xfcnf cm, fingerhutartig, l\xe4ngs gefaltet bis fast glatt, braun \u2014 er h\xe4ngt NUR AN DER SPITZE am Stiel.","Lang, wei\xdflich, kleiig, mit watteartigem Mark gef\xfcllt.","Keine Lamellen; der Hut ist wie eine Glocke \xfcber den Stiel gest\xfclpt und ringsum frei.","In feuchten Auw\xe4ldern bei Pappel und Weide; M\xe4rz bis Mai."])
B.buT=new A.bL(["Innen KAMMERIG gef\xfcllt, nicht durchgehend hohl \u2014 die Probe beim L\xe4ngshalbieren.","Angenehm w\xfcrzig; der Geruch warnt NICHT.","Vier bis zw\xf6lf cm, HIRNARTIG gewunden und gefurcht, nicht wabig, rotbraun bis dunkelbraun.","Kurz, dick, wei\xdflich, unregelm\xe4\xdfig gefurcht.","Keine Lamellen \u2014 die Sporen sitzen auf der gewundenen Oberfl\xe4che.","In Nadelw\xe4ldern auf sandigem Boden und an Brandstellen; M\xe4rz bis Mai."])
B.buH=new A.bL(["D\xfcnn und br\xfcchig, w\xe4ssrig braun.","Deutlich nach CHLOR oder Schwimmbad; roh giftig.","Kein Hut: ein f\xfcnf bis 15 cm breiter, anfangs tief BECHERF\xd6RMIGER Fruchtk\xf6rper, der sich ausbreitet und wellig verbiegt.","Nur ein kurzer, wei\xdflicher Stummel, der meist ganz im Boden steckt.","Weder Lamellen noch R\xf6hren; die olivbraune Innenseite tr\xe4gt das Sporenlager und ist grob ADERIG gerunzelt, au\xdfen wei\xdflich und kleiig.","In Auw\xe4ldern und an feuchten Wegr\xe4ndern, gern bei Esche und Pappel; M\xe4rz bis Mai."])
B.bvc=new A.bL(["Jung rein WEISS und ohne jede Zeichnung \u2014 l\xe4ngs halbieren ist Pflicht. Gelb oder braun hei\xdft: reif, nicht mehr essbar.","Jung mild und angenehm, reif muffig nach altem Staub.","Kein Hut: ein zwei bis sechs cm gro\xdfer, keulen- bis birnenf\xf6rmiger Fruchtk\xf6rper mit abgesetztem Stielteil, wei\xdf bis ockerbraun, mit abwischbaren Stacheln und K\xf6rnchen.","Der untere, sterile Teil ist als kurzer, schwammiger Stiel abgesetzt.","Keine Lamellen und keine R\xf6hren; reif \xf6ffnet sich oben ein Loch, aus dem die Sporen st\xe4uben.","In W\xe4ldern auf Boden und Nadelstreu, oft in Gruppen; Juni bis November."])
B.buW=new A.bL(["Jung rein WEISS und gleichm\xe4\xdfig wie Frischk\xe4se \u2014 l\xe4ngs durchschneiden ist Pflicht. Gelb oder oliv hei\xdft reif und nicht mehr essbar.","Jung angenehm pilzig, reif unangenehm streng.","Kein Hut: eine 20 bis 50 cm gro\xdfe, wei\xdfe Kugel ohne jeden Stiel, die Oberfl\xe4che wie Wildleder.","Fehlt vollst\xe4ndig; der Fruchtk\xf6rper sitzt mit einer Mycelschnur direkt dem Boden auf.","Weder Lamellen noch R\xf6hren noch Stacheln; die H\xfclle rei\xdft reif unregelm\xe4\xdfig auf und entl\xe4sst olivbraunes Sporenpulver.","Auf ged\xfcngten Wiesen, Weiden und in Parks, gern an Brennnessels\xe4umen; Juli bis Oktober."])
B.buZ=new A.bL(["Jung wei\xdf und fest, sp\xe4ter olivbraun und pulverig.","Jung mild und angenehm, reif muffig.","Kein Hut: ein zwei bis f\xfcnf cm gro\xdfer, deutlich BIRNENF\xd6RMIGER Fruchtk\xf6rper, jung wei\xdf, sp\xe4ter ockerbraun, feinwarzig bis glatt.","Ein kurzer, zusammengezogener Stielteil, aus dem WEISSE Mycelstr\xe4nge ins Holz ziehen.","Keine Lamellen und keine R\xf6hren; oben \xf6ffnet sich reif ein enges Loch, aus dem die Sporen st\xe4uben.","IMMER an morschem Holz, an St\xfcmpfen und vergrabenen Wurzeln, meist in dichten Rasen; Juli bis November."])
B.buK=new A.bL(["Wei\xdf, dick, z\xe4h-fest; alte Exemplare werden holzig.","Angenehm pilzig, mild.","F\xfcnf bis 20 cm, muschel- bis austernf\xf6rmig, grau, blaugrau bis braun, glatt.","Sehr kurz, seitlich angewachsen, oft fast fehlend, an der Basis filzig.","Wei\xdfe bis cremefarbene Lamellen, weit am Stielansatz HERABLAUFEND.","B\xfcschelig an Laubholz, vor allem Buche und Pappel; nach den ersten Fr\xf6sten, Oktober bis M\xe4rz."])
B.bvD=new A.bL(["Wei\xdf, d\xfcnn, weich.","Mild, schwach mehlig.","F\xfcnf bis 15 cm, wei\xdflich bis hell cremefarben, d\xfcnnfleischig und zerbrechlicher als der Austernseitling.","Kurz, seitlich bis exzentrisch, meist deutlicher ausgebildet als beim Austernseitling.","Wei\xdfe Lamellen, weit herablaufend.","An Laubholz, vor allem Buche; Mai bis September \u2014 die SOMMERform."])
B.bvg=new A.bL(["Jung saftig, weich und blassgelb, im Alter hart, faserig und br\xf6ckelig.","S\xe4uerlich-fruchtig; brauchbar sind nur die jungen, weichen R\xe4nder.","Dachziegelig \xfcbereinander stehende, 10 bis 40 cm breite Konsolen, schwefelgelb bis orange, am Rand wellig; alt blass und kreidig.","Kein Stiel; die Konsolen sitzen breit und seitlich am Stamm an.","Feine, schwefelgelbe PORENSCHICHT statt Lamellen, auf Druck dunkler werdend.","An lebenden und toten Laubb\xe4umen, vor allem Eiche, Weide und Obstb\xe4umen; Mai bis Juli."])
B.bv1=new A.bL(["Rot marmoriert wie ein St\xfcck Fleisch, saftig; im Schnitt tritt r\xf6tlicher Saft aus.","Schwach s\xe4uerlich, Geschmack deutlich SAUER.","Zehn bis 25 cm, zungen- bis leberf\xf6rmig, blutrot bis rotbraun, feucht klebrig und rau wie eine Katzenzunge.","Kein oder nur ein kurzer seitlicher Ansatz am Stamm.","Cremewei\xdfe bis rosa R\xd6HRCHEN, die EINZELN nebeneinander stehen und sich voneinander l\xf6sen lassen.","Am Stammfu\xdf alter Eichen, seltener an Esskastanien; August bis Oktober."])
B.bvQ=new A.bL(["GALLERTARTIG und elastisch wie Gummi, trocken hornhart, quillt bei N\xe4sse wieder auf.","Nahezu geruchlos, Geschmack mild.","Drei bis zehn cm, ohrmuschelf\xf6rmig und gewellt, rotbraun bis olivbraun, au\xdfen fein samtig behaart.","Kein Stiel; seitlich oder mit einem Punkt am Holz angewachsen.","Keine Lamellen: eine glatte bis aderig gefaltete, graubraune Fl\xe4che.","An totem Laubholz, vor allem HOLUNDER; das ganze Jahr, besonders in milden Wintern."])
B.buX=new A.bL(["D\xfcnn, blass, im Hut weich, im Stiel z\xe4h.","Angenehm pilzig, mild.","Drei bis sechs cm, honig- bis zimtbraun, glatt, bei Trockenheit von der Mitte her ZWEIFARBIG ausblassend.","Mit h\xe4utigem Ring; DARUNTER deutlich dunkel SCHUPPIG bis sch\xfclferig \u2014 das entscheidende Merkmal.","Lamellen jung blass, dann zimtbraun, am Stiel angewachsen.","Dicht b\xfcschelig an Laubholzst\xfcmpfen, selten Nadelholz; April bis November."])
B.bvS=new A.bL(["D\xfcnn, blassbraun.","MEHLIG bis ranzig \u2014 nicht angenehm pilzig.","Zwei bis f\xfcnf cm, ocker- bis honigbraun, glatt, hygrophan ausblassend \u2014 dem Stockschw\xe4mmchen zum Verwechseln \xe4hnlich.","Mit verg\xe4nglichem Ring; DARUNTER GLATT und silbrig l\xe4ngs\xfcberfasert, niemals schuppig.","Lamellen jung blass ocker, sp\xe4ter rostbraun, angewachsen.","Einzeln bis kleinb\xfcschelig an morschem Laub- und Nadelholz, oft neben Stockschw\xe4mmchen; das ganze Jahr."])
B.bvP=new A.bL(["Blassgelb, im Hut weich, im Stiel z\xe4h.","Mild, unauff\xe4llig.","Zwei bis acht cm, honiggelb bis orangebraun, bei Feuchtigkeit stark SCHLEIMIG gl\xe4nzend.","Z\xe4h, nach unten SAMTIG SCHWARZBRAUN \u2014 und OHNE jeden Ring.","Lamellen blassgelb, breit, entfernt stehend, angewachsen.","B\xfcschelig an Laubholz, besonders Weide und Pappel; Oktober bis M\xe4rz, auch bei Frost."])
B.buL=new A.bL(["Schwefelgelb und d\xfcnn, im Stiel z\xe4h-faserig.","Unauff\xe4llig, Geschmack sehr BITTER.","Zwei bis sechs cm, schwefelgelb mit rostbrauner Mitte, glatt.","Schlank, gelb, ohne echten Ring, oft mit dunkler Faserzone.","Lamellen jung schwefelgelb, bald deutlich GR\xdcNLICH, sp\xe4ter olivbraun.","In dichten B\xfcscheln an St\xfcmpfen von Laub- und Nadelholz; das ganze Jahr."])
B.bv6=new A.bL(["Wei\xdflich, im Stiel z\xe4h-faserig.","Streng, im Alter unangenehm; roh scharf.","Vier bis zw\xf6lf cm, honig- bis olivbraun, in der Mitte mit dunklen SCH\xdcPPCHEN.","Lang, faserig, mit deutlichem WATTIGEM Ring; die Stiele wachsen aus einem gemeinsamen B\xfcschel.","Lamellen wei\xdflich bis blass fleischfarben, im Alter rostfleckig, am Stiel etwas herablaufend.","In gro\xdfen B\xfcscheln an lebendem und totem Holz, auch an Wurzeln im Boden; August bis November."])
B.bvh=new A.bL(["Wei\xdf und fest, im Stiel z\xe4h und faserig.","Streng pilzig; roh GIFTIG, nur gut durchgegart und ohne das Kochwasser.","Drei bis 15 cm, dunkel rotbraun, dicht mit dunklen abstehenden SCHUPPEN besetzt, vor allem zur Mitte hin.","Fest und braun genattert, mit dickem wei\xdfem RING, der au\xdfen br\xe4unlich beflockt ist.","Lamellen wei\xdflich, im Alter rostfleckig, am Stiel etwas herablaufend.","An Nadelholz, vor allem Fichte, als Parasit an lebenden St\xe4mmen und an St\xfcmpfen; August bis November."])
B.bvi=new A.bL(["Wei\xdf, fest, ohne Verf\xe4rbung.","Stark nach frischem MEHL oder Gurke \u2014 das Hauptmerkmal.","F\xfcnf bis zw\xf6lf cm, cremewei\xdf bis hell ockerlich, glatt, oft unregelm\xe4\xdfig verbogen.","Wei\xdf, voll und fest, faserig; OHNE Ring und OHNE Scheide.","Lamellen wei\xdf und wei\xdf BLEIBEND, dicht, ausgebuchtet angewachsen.","In Hexenringen auf Wiesen, an Hecken und Waldr\xe4ndern; April bis Juni."])
B.bvw=new A.bL(["Wei\xdf, auf Druck r\xf6tend.","Unangenehm SPERMATISCH \u2014 nie mehlig.","Drei bis acht cm, wei\xdflich, mit dem Alter ZIEGELROT anlaufend, radialfaserig aufrei\xdfend.","Wei\xdflich, l\xe4ngsfaserig, r\xf6tend, ohne Ring.","Lamellen blass, sp\xe4ter olivbraun, r\xf6tend.","Bei Laubb\xe4umen auf Kalk, oft neben Maipilzen; Mai bis Juli."])
B.bvH=new A.bL(["Wei\xdf und fest, im Schnitt ohne Verf\xe4rbung.","Mehlartig, im Alter ranzig.","Zehn bis 20 cm, graubraun bis elfenbeinfarben, glatt, unregelm\xe4\xdfig gewellt.","Kr\xe4ftig und voll, wei\xdflich, l\xe4ngsfaserig, ohne Ring.","Lamellen jung gelblich, sp\xe4ter deutlich ROSA bis fleischrosa; ausgebuchtet angewachsen, nicht herablaufend.","Bei Laubb\xe4umen auf schweren, kalkhaltigen B\xf6den; Juni bis Oktober."])
B.bvz=new A.bL(["Wei\xdf, fest, elastisch.","Angenehm, schwach blaus\xe4ureartig.","Sechs bis 20 cm, ocker- bis lederbraun, jung gew\xf6lbt, sp\xe4ter tief TRICHTERIG eingedellt.","Kr\xe4ftig, keulig, wei\xdflich, ohne Ring.","Lamellen wei\xdf bis cremefarben, weit am Stiel HERABLAUFEND, dicht.","In Hexenringen in Laub- und Nadelw\xe4ldern; September bis November."])
B.buE=new A.bL(["Wei\xdf und weich, im Alter w\xe4ssrig und leicht madig.","Streng S\xdcSSLICH-parf\xfcmiert \u2014 unverwechselbar und aufdringlich.","Sechs bis 20 cm, grau bis graubraun, wie BEREIFT wirkend, jung gew\xf6lbt mit eingerolltem Rand.","Kr\xe4ftig, keulig verdickt, grauwei\xdf, ohne Ring.","Lamellen wei\xdflich bis cremefarben, dicht, am Stiel kurz herablaufend, leicht abl\xf6sbar.","In gro\xdfen Reihen und Hexenringen in Nadel- und Laubw\xe4ldern; September bis Dezember."])
B.buV=new A.bL(["Violettlich, fest.","Angenehm parf\xfcmiert, s\xfc\xdflich.","F\xfcnf bis 15 cm, violett bis blauviolett, im Alter lederbraun ausblassend, glatt.","Kr\xe4ftig, faserig, violett, an der Basis oft filzig, ohne Ring.","Lamellen violett, DICHT stehend und d\xfcnn, ausgebuchtet angewachsen.","Auf Laub und Nadelstreu, gern an Kompostr\xe4ndern; September bis Dezember."])
B.bvG=new A.bL(["D\xfcnn, violettlich.","Unauff\xe4llig, mild im Geschmack.","Ein bis f\xfcnf cm, violett, im Alter stark ausblassend, feinschuppig, mit gewelltem Rand.","D\xfcnn, z\xe4h-faserig, violett l\xe4ngsfaserig.","Lamellen violett, auff\xe4llig DICK und ENTFERNT stehend, am Stiel angewachsen.","In feuchten Laub- und Nadelw\xe4ldern, oft in Moos; Juli bis November."])
B.bvJ=new A.bL(["Gelblich, im Schnitt braun anlaufend.","S\xe4uerlich bis obstig.","F\xfcnf bis 15 cm, olivbraun bis rostbraun, samtig, mit lange stark EINGEROLLTEM, gerieftem Rand; im Alter trichterig.","Kurz, oft exzentrisch, olivbraun, ohne Ring.","Lamellen ockergelb, weit herablaufend, auf Druck deutlich braun fleckend; sie lassen sich vom Hut ABSCHIEBEN.","Bei Birke und Fichte, auf sauren B\xf6den und in G\xe4rten; Juli bis Oktober."])
B.bvt=new A.bL(["Gelblich bis br\xe4unlich.","Schwach rettichartig.","Drei bis acht cm, orangebraun bis fuchsig, FILZIG-rau, mit auff\xe4llig spitzem Buckel.","Schlank, gelblich, mit blassgelben Faserb\xe4ndern; ohne Ring.","Lamellen safran- bis zimtbraun, entfernt stehend, angewachsen.","In Nadelw\xe4ldern auf sauren, moosigen B\xf6den; August bis Oktober."])
B.bv8=new A.bL(["Gelblich bis ockerbraun.","Schwach rettichartig.","Drei bis zehn cm, orangebraun bis fuchsigrot, filzig-rau, gew\xf6lbt bis flach, ohne spitzen Buckel.","Gelbbraun, l\xe4ngsfaserig, ohne Ring.","Lamellen orangebraun bis zimtbraun, dick und entfernt stehend.","In w\xe4rmeren Laubw\xe4ldern bei Eiche und Buche; August bis Oktober."])
B.bvo=new A.bL(["Wei\xdf, fest, dick.","Mehlartig, Geschmack mild \u2014 die Milde warnt NICHT.","Sechs bis 15 cm, hellgrau mit dunkleren, konzentrisch angeordneten SCHUPPEN wie ein Tigermuster.","Kr\xe4ftig, wei\xdflich, fest, ohne Ring.","Lamellen wei\xdf bis cremefarben, dick, ausgebuchtet angewachsen; sie sondern manchmal Tr\xf6pfchen ab.","Bei Fichte und Buche auf Kalk, in Bergw\xe4ldern; August bis Oktober."])
B.bvr=new A.bL(["Wei\xdflich bis gelblich, fest.","Mehlartig, mild.","F\xfcnf bis zw\xf6lf cm, schwefel- bis olivgelb, in der Mitte br\xe4unlich, klebrig, oft mit Sand verbacken.","Kurz, gelb, meist tief im Sand steckend, ohne Ring.","Lamellen leuchtend SCHWEFELGELB, dicht, ausgebuchtet angewachsen.","In sandigen Kiefernw\xe4ldern und D\xfcnen, oft halb vergraben; September bis November."])
B.buC=new A.bL(["Blass und d\xfcnn, im Stiel z\xe4h und faserig.","W\xfcrzig nach Bittermandel oder Nelken, Geschmack mild.","Zwei bis f\xfcnf cm, ledergelb bis hellbraun, jung glockig, sp\xe4ter flach mit stumpfem Buckel; trocknet aus und lebt bei Regen wieder auf.","D\xfcnn und z\xe4h wie Draht, hellbraun; l\xe4sst sich verdrehen, ohne zu brechen.","Lamellen blass ockerfarben, dick, auffallend WEIT stehend und am Stiel frei endend.","Auf Wiesen, Rasen und an Wegr\xe4ndern, oft in HEXENRINGEN; Mai bis November."])
B.bvd=new A.bL(["Wei\xdf und weich, im Hut d\xfcnn, im Schnitt ohne Verf\xe4rbung.","Schwach rettichartig, Geschmack mild.","Vier bis zw\xf6lf cm, graubraun bis rehbraun und radialfaserig, jung glockig, sp\xe4ter flach mit Buckel.","Wei\xdflich mit dunklen L\xe4ngsfasern, ohne Ring, an der Basis leicht verdickt.","Lamellen jung wei\xdf, bald FLEISCHROSA durch das Sporenpulver, frei stehend und dicht.","An morschem Laub- und Nadelholz, auf S\xe4gemehl und Rindenmulch; fast ganzj\xe4hrig, Schwerpunkt Mai bis Oktober."])
B.bvC=new A.bL(["Wei\xdf und fest, im Schnitt unver\xe4ndert.","Angenehm pilzig, Geschmack mild und nussig.","F\xfcnf bis 20 cm, jung weinrot bis rotbraun, sp\xe4ter ockerbraun ausblassend, trocken und glatt.","Kr\xe4ftig und wei\xdf, mit dickem Ring, dessen Oberseite STERNF\xd6RMIG gefurcht ist.","Lamellen jung blassgrau, dann VIOLETTSCHWARZ, breit am Stiel angewachsen.","Auf Stroh, Holzh\xe4cksel und Komposterde in G\xe4rten und Beeten, selten im Wald; Juni bis Oktober."])
B.buJ=new A.bL(["D\xfcnn, blass orangebraun und w\xe4ssrig.","Schwach s\xfc\xdflich, Geschmack mild.","Vier bis zehn cm, fuchsig orangebraun, bald tief TRICHTERIG mit lange eingerolltem Rand, feucht wasserfleckig.","Schlank, in Hutfarbe, an der Basis wei\xdffilzig, ohne Ring.","Lamellen gleichfarben bis heller, sehr gedr\xe4ngt, weit herablaufend und leicht vom Hut abzul\xf6sen.","In Reihen und Hexenringen auf Nadelstreu, oft in Fichtenforsten; September bis Dezember."])
B.buA=new A.bL(["Wei\xdf bis blassgelb, weich, im Schnitt unver\xe4ndert.","Mild und angenehm pilzig, Geschmack nussig.","F\xfcnf bis zw\xf6lf cm, ockergelb bis semmelfarben, jung wie von WEISSEM Reif \xfcberzogen; der Scheitel bleibt runzelig.","Kr\xe4ftig und wei\xdflich, mit h\xe4utigem aufsteigendem Ring und einer bandartigen Zone darunter.","Lamellen jung blass, sp\xe4ter TONBRAUN durch das Sporenpulver, am Stiel angewachsen.","Bei Fichte und Birke auf saurem Boden, gern zwischen Heidelbeeren; August bis Oktober."])
