B.aP=new A.dV(B.c_,null)
B.fr=new A.xn("Nur gegart, roh giftig",1,"nurGegart")
B.f7=new A.dV(B.fr,null)
B.bol=new A.dV(B.c_,"Der Name meint mehrere Arten der Gattung Leccinum; sie gelten alle als Speisepilze und sind alle roh unvertr\xe4glich.")
B.br5=new A.dV(B.c_,"Die schleimige Huthaut wird meist abgezogen; sie kann abf\xfchrend wirken.")
B.boU=new A.dV(B.fr,"Roh giftig. Gegart ein gesch\xe4tzter Speisepilz \u2014 die Blauf\xe4rbung beim Anschnitt ist kein Giftzeichen.")
B.bn0=new A.dV(B.fr,"Roh giftig, und auch gegart nicht von jedem vertragen.")
B.Fd=new A.xn("Ungenie\xdfbar",3,"ungeniessbar")
B.boZ=new A.dV(B.Fd,"Bitter, nicht giftig \u2014 ein einziger verdirbt aber ein ganzes Gericht. Wird mit dem Steinpilz verwechselt.")
B.lN=new A.dV(B.fq,null)
B.bo0=new A.dV(B.Fd,"Gallenbitter \u2014 ein einziger verdirbt das Gericht, und roh oder in Menge macht er Magen-Darm-Beschwerden. Wird f\xfcr Steinpilz oder Hexenr\xf6hrling gehalten.")
B.ky=new A.xn("Uneinheitlich beurteilt",2,"umstritten")
B.bog=new A.dV(B.ky,"Uneinheitlich beurteilt \u2014 nicht giftig im engeren Sinn, kann aber Magen-Darm-Beschwerden ausl\xf6sen.")
B.bp4=new A.dV(B.c_,"Junge Champignons werden mit jungen Knollenbl\xe4tterpilzen verwechselt \u2014 die haben wei\xdfe Lamellen und eine Scheide am Stielgrund.")
B.bp_=new A.dV(B.fq,"L\xe4uft an der Stielbasis chromgelb an und riecht beim Erhitzen nach Karbol. Die h\xe4ufigste Champignon-Vergiftung.")
B.bqY=new A.dV(B.c_,"Nur ausgewachsene Exemplare mit genattertem Stiel und verschiebbarem Ring \u2014 H\xfcte unter zehn Zentimetern stehen lassen: Kleine Schirmlinge sind zum Teil t\xf6dlich giftig, und die sind in diesem Verzeichnis nicht einmal aufgef\xfchrt.")
B.bpI=new A.dV(B.ky,"Der Name meint mehrere Arten der Gattung Chlorophyllum. Roh giftig, und auch gegart werden sie nicht von jedem vertragen.")
B.boe=new A.dV(B.c_,"Nur solange die Lamellen wei\xdf sind \u2014 er zerflie\xdft innerhalb weniger Stunden zu schwarzer Tinte.")
B.boQ=new A.dV(B.fr,"Roh giftig. Wird mit dem giftigen Pantherpilz verwechselt \u2014 der eine r\xf6tet im Fleisch und an Fra\xdfstellen, der andere nicht.")
B.bqy=new A.dV(B.fs,"Die mit Abstand h\xe4ufigste t\xf6dliche Pilzvergiftung in Mitteleuropa. Die Beschwerden beginnen erst Stunden sp\xe4ter, wenn die Leber bereits gesch\xe4digt ist.")
B.Ae=new A.dV(B.fs,null)
B.boo=new A.dV(B.fr,"Roh giftig. Ein Wulstling ohne Ring \u2014 die Verwechslung geht in Richtung der Knollenbl\xe4tterpilze.")
B.bpn=new A.dV(B.c_,"Gr\xfcnh\xfctige T\xe4ublinge werden mit dem Gr\xfcnen Knollenbl\xe4tterpilz verwechselt \u2014 T\xe4ublinge haben keine Scheide und keinen Ring.")
B.bmt=new A.dV(B.fq,"Brennend scharf; f\xfchrt roh zu Erbrechen.")
B.bpL=new A.dV(B.fq,"In Mitteleuropa ein Giftpilz (Magen-Darm). Dass er in Osteuropa nach langem Abkochen gegessen wird, ist kein Freibrief. Wird wegen der Stielgr\xfcbchen und verblasst fast gleicher Farbe f\xfcr einen Reizker gehalten \u2014 den Unterschied tr\xe4gt die Milch.")
B.bqa=new A.dV(B.fr,"Roh giftig \u2014 das gilt f\xfcr alle Morcheln.")
B.bqX=new A.dV(B.fs,'Trotz des wissenschaftlichen Namens \u201eesculenta" (essbar): Das Gift Gyromitrin ist fl\xfcchtig, aber auch die D\xe4mpfe beim Kochen sind gef\xe4hrlich. Galt fr\xfcher als Speisepilz.')
B.blB=new A.dV(B.ky,"Uneinheitlich beurteilt \u2014 roh giftig, und auch gegart sind Unvertr\xe4glichkeiten beschrieben.")
B.brH=new A.dV(B.c_,"Nur solange das Fleisch rein wei\xdf ist. Gelb oder braun hei\xdft: reife Sporen, nicht mehr essbar.")
B.brh=new A.dV(B.c_,"Nur jung und innen rein wei\xdf. Halbiert man einen St\xe4ubling und sieht darin einen angelegten Pilz, ist es ein junger Knollenbl\xe4tterpilz.")
B.blY=new A.dV(B.fr,"Nur die jungen, weichen R\xe4nder. An Eibe, Robinie und Eukalyptus gewachsen gilt er als unvertr\xe4glich.")
B.boH=new A.dV(B.c_,"Jung mild, mit dem Alter zunehmend bitter.")
B.bpy=new A.dV(B.ky,"Der Name meint die ganze Gattung Ramaria. Einige Arten gelten als Speisepilze, andere wirken abf\xfchrend, und auseinanderhalten lassen sie sich im Feld kaum.")
B.bn9=new A.dV(B.c_,"In Deutschland besonders gesch\xfctzt \u2014 wild wachsende Exemplare d\xfcrfen nicht gesammelt werden. Im Handel stammt er aus Zucht.")
B.bmn=new A.dV(B.fr,"Wird mit dem t\xf6dlich giftigen Gifth\xe4ubling verwechselt, der am selben Holz w\xe4chst. Ohne sichere Bestimmung nicht sammeln.")
B.brS=new A.dV(B.c_,"Zur selben Zeit am selben Ort wachsen der giftige Ziegelrote Risspilz und der Riesenr\xf6tling.")
B.boO=new A.dV(B.fr,"Roh giftig, und auch gegart nicht von jedem vertragen. Das Kochwasser wird \xfcblicherweise weggegossen.")
B.blq=new A.dV(B.ky,"Uneinheitlich beurteilt \u2014 roh giftig, und Unvertr\xe4glichkeiten sind auch gegart beschrieben.")
B.bro=new A.dV(B.ky,"Galt lange als Speisepilz und steht heute zugleich auf der Giftpilzliste: h\xe4ufige Unvertr\xe4glichkeiten, dazu der Verdacht einer erbgutsch\xe4digenden Wirkung.")
B.bnY=new A.dV(B.fr,"Roh giftig. W\xe4chst im Winter am selben Holz wie der t\xf6dlich giftige Gifth\xe4ubling.")
B.bmV=new A.dV(B.fs,"Dasselbe Gift wie im Gr\xfcnen Knollenbl\xe4tterpilz. Wird mit dem Stockschw\xe4mmchen verwechselt.")
B.bov=new A.dV(B.fs,"Wurde jahrzehntelang als Speisepilz gesammelt. Das Gift wirkt nicht beim ersten Mal: Der K\xf6rper bildet Antik\xf6rper, und irgendwann zerst\xf6ren sie nach einer Mahlzeit die roten Blutk\xf6rperchen.")
B.bqo=new A.dV(B.fs,"Zerst\xf6rt die Nieren. Die ersten Beschwerden kommen erst nach Tagen bis Wochen \u2014 bis dahin denkt niemand mehr an den Pilz.")
